import collections,json,pathlib
p=pathlib.Path("research/results/quadratic_sum_source_audit_20260914_141/bounded-probe-source-checks.jsonl")
counts=collections.Counter();selected=[]
with p.open() as f:
    for line in f:
        r=json.loads(line);counts[r["record"]]+=1
        if r["record"] in ("sum_source_summary","summary","sum_span_control"):
            selected.append(r)
        elif r["record"]=="functional_quotient_matrix":
            selected.append({k:r[k] for k in ("record","normal_image_dimension","functional_rank")})
        elif r["record"]=="bounded_probe_parameters":
            selected.append({k:r[k] for k in ("record","ell","r","s","S","range_space_image_conditions","old_degree_condition")})
print(json.dumps({"record_counts":dict(counts),"selected":selected},indent=2))
